const body = $input.first()?.json?.body || $input.first()?.json || {};
const candidates = body.candidates || [];
const collectedAt = new Date().toISOString();

if (!Array.isArray(candidates) || candidates.length === 0) {
  return [];
}

return candidates.map((c, index) => {
  const matchedKws = Array.isArray(c.matched_keywords) 
    ? c.matched_keywords.join(', ') 
    : (c.matched_keywords || '');

  return {
    json: {
      id: c.post_text_hash ? c.post_text_hash.substring(0, 16) : `lead_${Date.now()}_${index}`,
      platform: c.platform || 'web',
      post_url: c.post_url || '',
      author_name: c.author_name || 'Public Poster',
      author_url: c.author_url || '',
      post_text: c.post_text || '',
      posted_at: c.posted_at || collectedAt,
      matched_keywords: matchedKws,
      source_query: c.source_query || '',
      post_text_hash: c.post_text_hash || '',
      collected_at: collectedAt
    }
  };
});
